#!/usr/bin/env node
// WakeWise — original, first-party alarm chime generator.
//
// Produces public/audio/wakewise-alarm-chime.wav entirely from
// mathematically synthesised sine tones (no samples, no recordings, no
// third-party audio of any kind, no copyrighted melody) so the file can
// be regenerated byte-for-byte from this script alone. See
// docs/wakewise-alarm-sound-provenance.md for the full provenance record.
//
// Sound design: four individual sine tones - C5, E5, G5, then a higher C6
// "resolution" - each with its own gentle attack (a short raised-cosine
// ramp, avoiding a harsh click) and an exponential ("bell-like") decay.
// The tones overlap in onset (a soft ascending arpeggio, not four
// sequential beeps) rather than following any recognisable existing
// melody. A short true-silence pad follows the final decay so a looping
// player (the real foreground alarm loops until Begin/Remind/Skip) always
// restarts during silence rather than mid-decay.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const SAMPLE_RATE = 44100;
const BITS_PER_SAMPLE = 16;
const CHANNELS = 1;

// Musical content - four pure sine tones, standard equal-temperament
// frequencies (Hz). Not a transcription of any existing recognisable
// melody: a simple four-note ascending arpeggio (root, major third,
// perfect fifth, octave-plus-major-third "resolution"), the same
// generic tonal shape used constantly in original film/UI-sound scoring
// and not attributable to any specific copyrighted work.
const NOTES = [
  { name: 'C5', freq: 523.25, onset: 0.15, decaySeconds: 3.4, peakAmp: 1.0 },
  { name: 'E5', freq: 659.25, onset: 1.0, decaySeconds: 3.4, peakAmp: 0.92 },
  { name: 'G5', freq: 783.99, onset: 1.85, decaySeconds: 3.6, peakAmp: 0.88 },
  { name: 'C6', freq: 1046.5, onset: 2.9, decaySeconds: 4.4, peakAmp: 0.8 }
];

const ATTACK_SECONDS = 0.02; // 20ms raised-cosine attack - gentle, no click
const TRAILING_SILENCE_SECONDS = 1.0; // smooth pause before a loop restart
const TARGET_PEAK_DBFS = -7.5; // within the required -6 to -9 dBFS range

const lastNoteEnd = Math.max(...NOTES.map((n) => n.onset + n.decaySeconds));
const TOTAL_SECONDS = lastNoteEnd + TRAILING_SILENCE_SECONDS;
const totalSamples = Math.round(TOTAL_SECONDS * SAMPLE_RATE);

// One note's instantaneous amplitude envelope at time t (seconds) since
// the note's own onset: 0 before onset, a raised-cosine ramp for the
// first ATTACK_SECONDS (smooth start, no discontinuity/click), then a
// pure exponential decay - the "bell-like" shape - reaching a negligible
// fraction of its peak by decaySeconds.
const envelope = (tSinceOnset, decaySeconds) => {
  if (tSinceOnset < 0) return 0;
  if (tSinceOnset < ATTACK_SECONDS) {
    return 0.5 * (1 - Math.cos((Math.PI * tSinceOnset) / ATTACK_SECONDS));
  }
  // Exponential decay constant chosen so the envelope reaches ~1% of
  // its peak (-40dB) by decaySeconds - a natural, complete bell decay
  // rather than an abrupt cutoff.
  const decayConstant = decaySeconds / Math.log(100);
  return Math.exp(-(tSinceOnset - ATTACK_SECONDS) / decayConstant);
};

const samplesFloat = new Float64Array(totalSamples);
let peak = 0;

for (let i = 0; i < totalSamples; i++) {
  const t = i / SAMPLE_RATE;
  let value = 0;
  for (const note of NOTES) {
    const tSinceOnset = t - note.onset;
    const env = envelope(tSinceOnset, note.decaySeconds);
    if (env > 0) {
      value += note.peakAmp * env * Math.sin(2 * Math.PI * note.freq * t);
    }
  }
  samplesFloat[i] = value;
  const abs = Math.abs(value);
  if (abs > peak) peak = abs;
}

// Normalise to the exact target peak level - guarantees no clipping and
// lands precisely within the required -6..-9 dBFS range regardless of
// how the four overlapping tones happen to sum.
const targetPeakLinear = 10 ** (TARGET_PEAK_DBFS / 20);
const scale = peak > 0 ? targetPeakLinear / peak : 0;

const dataBytes = totalSamples * CHANNELS * (BITS_PER_SAMPLE / 8);
const buffer = Buffer.alloc(44 + dataBytes);

// RIFF/WAVE header - standard 44-byte canonical PCM WAV header.
buffer.write('RIFF', 0, 'ascii');
buffer.writeUInt32LE(36 + dataBytes, 4);
buffer.write('WAVE', 8, 'ascii');
buffer.write('fmt ', 12, 'ascii');
buffer.writeUInt32LE(16, 16); // fmt chunk size (PCM)
buffer.writeUInt16LE(1, 20); // audio format: 1 = PCM
buffer.writeUInt16LE(CHANNELS, 22);
buffer.writeUInt32LE(SAMPLE_RATE, 24);
const byteRate = SAMPLE_RATE * CHANNELS * (BITS_PER_SAMPLE / 8);
buffer.writeUInt32LE(byteRate, 28);
const blockAlign = CHANNELS * (BITS_PER_SAMPLE / 8);
buffer.writeUInt16LE(blockAlign, 32);
buffer.writeUInt16LE(BITS_PER_SAMPLE, 34);
buffer.write('data', 36, 'ascii');
buffer.writeUInt32LE(dataBytes, 40);

let offset = 44;
for (let i = 0; i < totalSamples; i++) {
  const scaled = Math.max(-1, Math.min(1, samplesFloat[i] * scale));
  const int16 = Math.round(scaled * 32767);
  buffer.writeInt16LE(int16, offset);
  offset += 2;
}

const outPath = path.join(fileURLToPath(new URL('.', import.meta.url)), '..', 'public', 'audio', 'wakewise-alarm-chime.wav');
writeFileSync(outPath, buffer);

const finalPeakDbfs = 20 * Math.log10(targetPeakLinear);
console.log(`Wrote ${outPath}`);
console.log(`Duration: ${TOTAL_SECONDS.toFixed(2)}s, ${totalSamples} samples @ ${SAMPLE_RATE}Hz, ${BITS_PER_SAMPLE}-bit mono`);
console.log(`Peak level: ${finalPeakDbfs.toFixed(2)} dBFS (target ${TARGET_PEAK_DBFS} dBFS)`);
console.log(`File size: ${buffer.length} bytes`);
